/* Per-user sign-in UI. Account codes are generated by the Worker and are
   never sent in a URL. Login must finish before showing any service records. */
(function(){
  "use strict";
  const ACTIVE="carServiceActiveAccountV3";
  const $=id=>document.getElementById(id);
  const gate=$("accountGate"),message=$("accountMessage"),login=$("accountLoginForm"),
    codeInput=$("accountCode"),create=$("accountCreate"),created=$("accountCreated"),
    loginPanel=$("accountLoginPanel"),registerPanel=$("accountRegisterPanel"),
    registerChoices=$("accountRegisterChoices"),backToLogin=$("accountBackToLogin");
  if(!gate)return;
  let busy=false,pendingAccount=null,current=null;
  // Match the Worker: accept custom visible text, including Greek characters.
  const normalizeCode=raw=>String(raw??"").trim().normalize("NFKC").toUpperCase();
  const codeValid=code=>code.length>0 && [...code].length<=64 &&
    code.length<=128 && !/[\p{Cc}\p{Cf}\p{Cs}\p{Zl}\p{Zp}]/u.test(code);
  const sessionFormat=/^ST-[a-f0-9]{64}-[A-F0-9]{48}$/;
  function customCode(raw){
    const value=normalizeCode(raw);
    if(!codeValid(value))throw new Error("Γράψε έναν κωδικό έως 64 χαρακτήρες.");
    return value;
  }
  const scopeFormat=/^[a-f0-9]{64}$/;
  function notice(text,error=false){
    message.textContent=text;message.classList.toggle("error",error);
  }
  function setBusy(flag){
    busy=flag;
    for(const b of [create,$("accountOpenRegister"),backToLogin,$("accountCustomCreate"),
      $("accountLoginBtn"),$("accountCopy"),$("accountContinue")]){
      b.disabled=flag;
    }
  }
  async function api(path,body,auth){
    const result=await fetch(path,{
      method:"POST",cache:"no-store",
      headers:{"Content-Type":"application/json",...(auth?{"Authorization":"Bearer "+auth}:{})},
      body:JSON.stringify(body||{})
    });
    const data=await result.json().catch(()=>({}));
    if(!result.ok)throw new Error(data.error||"Η υπηρεσία δεν απάντησε ("+result.status+").");
    return data;
  }
  function valid(data){
    return data&&typeof data.code==="string"&&codeValid(data.code)&&
      scopeFormat.test(data.scope)&&sessionFormat.test(data.session||"");
  }
  async function scopeOf(code){
    const bytes=new TextEncoder().encode(code);
    const digest=await crypto.subtle.digest("SHA-256",bytes);
    return Array.from(new Uint8Array(digest),b=>b.toString(16).padStart(2,"0")).join("");
  }
  function start(data){
    if(!valid(data))throw new Error("Η σύνδεση χρειάζεται επαλήθευση από τον server.");
    current=data;
    localStorage.setItem(ACTIVE,JSON.stringify(data));
    gate.hidden=true;
    document.body.classList.remove("account-locked");
    window.CarAppStartAccount(data.session||data.code,data.scope);
  }
  async function verify(code,silent=false){
    const formatted=normalizeCode(code);
    if(!codeValid(formatted))throw new Error("Συμπλήρωσε τον προσωπικό σου κωδικό.");
    let saved=null;
    try{saved=JSON.parse(localStorage.getItem(ACTIVE)||"null");}catch{}
    try{
      // A saved session does not use up PIN login attempts on each app launch.
      if(valid(saved)&&saved.code===formatted&&sessionFormat.test(saved.session||"")){
        try{
          const checked=await api("/api/account/session",{},saved.session);
          if(checked.scope===saved.scope){start(saved);return;}
        }catch{ /* Expired session: perform a fresh PIN login below. */ }
      }
      const result=await api("/api/account/login",{code:formatted});
      start({code:formatted,scope:result.scope,session:result.session});
    }catch(error){
      // Offline access is limited to a session already authenticated on this device.
      if(!navigator.onLine&&valid(saved)&&saved.code===formatted&&
          (await scopeOf(formatted))===saved.scope&&
          sessionFormat.test(saved.session||"")){
        start(saved);return;
      }
      if(!silent)throw error;
      localStorage.removeItem(ACTIVE);
      notice("Συνδέσου με τον προσωπικό σου κωδικό.",true);
    }
  }
  login.addEventListener("submit",async event=>{
    event.preventDefault();if(busy)return;
    setBusy(true);notice("Έλεγχος λογαριασμού…");
    try{await verify(codeInput.value);notice("");}
    catch(error){notice(error.message,true)}
    finally{setBusy(false)}
  });
  function showPanel(panel){
    if(busy)return;
    const registering=panel==="register";
    loginPanel.hidden=registering;
    registerPanel.hidden=!registering;
    notice("");
  }
  $("accountOpenRegister").addEventListener("click",()=>showPanel("register"));
  backToLogin.addEventListener("click",()=>showPanel("login"));

  function showCreated(data){
    if(!valid(data))throw new Error("Δεν επιστράφηκε έγκυρος κωδικός.");
    pendingAccount=data;
    $("accountNewCode").textContent=data.code;
    registerChoices.hidden=true;
    backToLogin.hidden=true;
    created.hidden=false;
    notice("Φύλαξε τον κωδικό σου πριν συνεχίσεις.");
  }
  $("accountCustomForm").addEventListener("submit",async event=>{
    event.preventDefault();
    if(busy)return;
    let code;
    try{code=customCode($("accountCustomCode").value);}
    catch(error){notice(error.message,true);return;}
    setBusy(true);notice("Έλεγχος διαθέσιμου κωδικού…");
    try{showCreated(await api("/api/account/create",{code}));}
    catch(error){notice(error.message,true);}
    finally{setBusy(false);}
  });
  create.addEventListener("click",async()=>{
    if(busy)return;
    setBusy(true);notice("Δημιουργία προσωπικού χώρου…");
    try{
      showCreated(await api("/api/account/create",{}));
    }catch(error){notice(error.message,true)}
    finally{setBusy(false)}
  });
  $("accountCopy").addEventListener("click",async()=>{
    if(!pendingAccount)return;
    try{await navigator.clipboard.writeText(pendingAccount.code);notice("Ο κωδικός αντιγράφηκε. Φύλαξέ τον σε ασφαλές μέρος.");}
    catch{notice("Επίλεξε τον κωδικό για χειροκίνητη αντιγραφή.",true);}
  });
  $("accountContinue").addEventListener("click",()=>{
    if(!pendingAccount)return;
    try{start(pendingAccount);}catch(error){notice(error.message,true);}
  });
  function logout(){
    if(!current)return;
    const pending=localStorage.getItem("carServiceSyncPendingV2:"+current.scope)==="1";
    if(pending){
      notice("Υπάρχουν αλλαγές που δεν συγχρονίστηκαν. Συνδέσου στο internet πριν αποσυνδεθείς.",true);
      alert("Πρώτα συγχρόνισε τις εκκρεμείς αλλαγές ή κράτησε αντίγραφο ασφαλείας.");
      return;
    }
    if(!confirm("Αποσύνδεση από αυτόν τον λογαριασμό; Το ιστορικό στον server δεν θα διαγραφεί."))return;
    // Shared devices must not keep a local copy of the previous person's data.
    const keys=["carServiceLog","carServiceSettings","carServiceReminders",
      "carServiceSyncBaseV2","carServiceSyncPendingV2","carServicePass",
      "carServiceDraftV1","carServiceAiConversationV1"];
    for(const k of keys)localStorage.removeItem(k+":"+current.scope);
    localStorage.removeItem(ACTIVE);
    location.reload();
  }
  window.CarAccountLogout=logout;
  window.CarAccountLock=()=>{
    localStorage.removeItem(ACTIVE);
    location.reload();
  };
  window.CarAccountShowCode=async()=>{
    if(!current)return;
    const code=current.code;
    try{
      await navigator.clipboard.writeText(code);
      $("bkmsg").textContent="Ο προσωπικός κωδικός αντιγράφηκε.";
    }catch{
      prompt("Αντίγραψε τον προσωπικό σου κωδικό:",code);
    }
  };
  $("legacyTransfer").addEventListener("click",async()=>{
    if(!current||busy)return;
    const legacyCode=$("legacyAccountCode").value.trim();
    if(!legacyCode){$("legacyStatus").textContent="Συμπλήρωσε τον παλιό κωδικό.";return;}
    if(!confirm("Να μεταφερθεί το παλιό ιστορικό στον ΤΩΡΙΝΟ λογαριασμό; Βεβαιώσου ότι έχεις φυλάξει τον νέο προσωπικό κωδικό."))return;
    busy=true;$("legacyTransfer").disabled=true;$("legacyStatus").textContent="Μεταφέρεται το παλιό ιστορικό…";
    try{
      await api("/api/account/migrate",{legacyCode},current.session||current.code);
      window.CarAppCopyLegacyLocal();
      $("legacyAccountCode").value="";
      $("legacyStatus").textContent="Η μεταφορά ολοκληρώθηκε. Επαναφόρτωση…";
      location.reload();
    }catch(error){
      $("legacyStatus").textContent=error.message;
    }finally{busy=false;$("legacyTransfer").disabled=false;}
  });
  window.addEventListener("storage",event=>{
    if(event.key!==ACTIVE||!current)return;
    try{
      const now=JSON.parse(event.newValue||"null");
      if(now?.scope!==current.scope)location.reload();
    }catch{location.reload()}
  });
  let last=null;
  try{last=JSON.parse(localStorage.getItem(ACTIVE)||"null");}catch{localStorage.removeItem(ACTIVE);}
  if(valid(last)){
    codeInput.value=last.code;
    notice("Επαλήθευση προηγούμενου λογαριασμού…");
    verify(last.code,true).catch(()=>notice("Συνδέσου ξανά με τον κωδικό σου.",true));
  }
})();